$ErrorActionPreference = 'Stop'
$root = (Resolve-Path "$PSScriptRoot/../../..").Path
$utf8 = [Text.UTF8Encoding]::new($false)
$entries = @()
foreach ($line in (Get-Content "$PSScriptRoot/asset_index.tsv")) {
    $v = $line.Split("`t")
    $w = [int]$v[1]; $h = [int]$v[2]
    $name = $v[0]
    $kind = if ($name.StartsWith('native/')) {'native_ui'} elseif ($name.StartsWith('mockup')) {'mockup'} elseif ($name.StartsWith('preview') -or $name -eq 'overview') {'preview'} else {'ui_sprite'}
    $entries += [ordered]@{file="$name.png";size=@($w,$h);pivot_pixels_top_left=@(($w/2),($h/2));pivot_unity_normalized=@(0.5,0.5);nine_slice_lbrt=@(0,0,0,0);kind=$kind;frames=1}
}
$manifest = [ordered]@{
    card='K-090';version=1;type='radial_ui';asset_root='Docs/References/codex_k090_v1';
    coordinates='top-left, x right, y down; angles clockwise from north';
    import=[ordered]@{texture_type='Sprite (2D and UI)';filter='Point';compression='None';mipmaps=$false;alpha_is_transparency=$true;mesh='Full Rect';pixels_per_unit=100};
    scale=[ordered]@{art_native_to_game=3;resampling='nearest-neighbor';direction_native_cell=@(74,74);direction_game_cell=@(222,222);amount_native_cell=@(120,120);amount_game_cell=@(360,360);typography='compass sprites are crisp 36x36 final-resolution raster glyphs, no native duplicate';character_sheet_contract='not applicable: UI, no foot baseline'};
    direction=[ordered]@{pivot=@(111,111);size=@(222,222);order=@('north','east','south','west');labels=@('북','동','남','서');centers_clockwise_degrees=@(0,90,180,270);hit_radius=@(48,108);half_sector_degrees=43;gap_action='no action';hub='direction_hub.png';hub_top_left=@(66,66);hub_text_safe_rect=@(79,96,64,30);dynamic_count='40명 is an example, render runtime text';label_centers=@(@(111,46),@(176,111),@(111,176),@(46,111));pointer_centers=@(@(111,20),@(202,111),@(111,202),@(20,111));layer_order=@('direction_base','quadrants','direction_hub','compass','pointer','runtime count');disabled='desaturated rim and slash, disable hit action; hide pointer and dim glyph at integration'};
    amount=[ordered]@{pivot=@(180,180);size=@(360,360);order=@('one','half','all');labels=@('1분대 보내기','1/2 보내기','전체 보내기');centers_clockwise_degrees=@(0,120,240);hit_radius=@(45,177);half_sector_degrees=58;gap_action='no action';hub='amount_hub.png';hub_top_left=@(141,141);content_centers=@(@(180,75),@(264,235),@(96,235));label_font_pixels=24;icons=@('icon_one','icon_half','icon_all');number_badges='existing HudArt/Command/command_number_1..3.png, read only';hover_underline='existing HudArt/Command/command_underline.png';next='same direction picker at same cursor anchor; remove amount wheel first'};
    selection=[ordered]@{corners=@('tl','tr','br','bl');corner_size=@(24,24);edge_horizontal_tile=@(24,6);edge_vertical_tile=@(6,24);tile_mode='Repeat, no stretching; 15px brass dash + 9px gap';nine_slice='disabled for all sprites; compose four fixed corners and repeated edges';selected_ring_size=@(72,30);selected_ring_pivot_pixels_top_left=@(36,15);selected_ring_pivot_unity_normalized=@(0.5,0.5);flag_ground_anchor='align ring center to flag pole ground point';selection_fill='transparent'};
    sheets=@([ordered]@{file='direction_states_sheet.png';cell=@(222,222);grid=@(4,3);columns=@('north','east','south','west');rows=@('normal','hover','disabled');pivot_per_cell=@(111,111)},[ordered]@{file='amount_states_sheet.png';cell=@(360,360);grid=@(3,3);columns=@('one','half','all');rows=@('normal','hover','disabled');pivot_per_cell=@(180,180)},[ordered]@{file='native/direction_states_sheet.png';cell=@(74,74);grid=@(4,3);columns=@('north','east','south','west');rows=@('normal','hover','disabled');pivot_per_cell=@(37,37)},[ordered]@{file='native/amount_states_sheet.png';cell=@(120,120);grid=@(3,3);columns=@('one','half','all');rows=@('normal','hover','disabled');pivot_per_cell=@(60,60)});
    sources=[ordered]@{wood='wood_source.png: built-in image generation, then palette-quantized and masked deterministically';existing_hud='Game/Assets/_Project/Art/UI/Resources/HudArt/Command';map_capture='Docs/References/codex_k020_v1/reference_map.png (historical saved map capture, not a fresh game capture)';night_capture='Docs/References/night_levels_20261020.png, upper-right quadrant 0.35';mockups='1920x1080 composites; added flags and UI are illustrative; no Unity capture performed';font='Windows Malgun Gothic Bold rasterized locally; font file not redistributed'};
    files=$entries
}
[IO.File]::WriteAllText("$PSScriptRoot/manifest.json",($manifest | ConvertTo-Json -Depth 14),$utf8)
$assets = [ordered]@{}
foreach ($e in $entries) {if ($e.kind -ne 'native_ui') {$assets[$e.file.Replace('.png','')] = 'data:image/png;base64,'+[Convert]::ToBase64String([IO.File]::ReadAllBytes("$PSScriptRoot/$($e.file)"))}}
foreach ($n in @('command_band_normal','command_band_hover','command_number_1','command_number_2','command_number_3','command_underline')) {$assets[$n]='data:image/png;base64,'+[Convert]::ToBase64String([IO.File]::ReadAllBytes("$root/Game/Assets/_Project/Art/UI/Resources/HudArt/Command/$n.png"))}
$assets['map_source']='data:image/png;base64,'+[Convert]::ToBase64String([IO.File]::ReadAllBytes("$root/Docs/References/codex_k020_v1/reference_map.png"))
$html = @'
<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>K-090 분대 명령 원형 UI</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#101713;color:#e5e4d3;font:17px/1.65 'Malgun Gothic',sans-serif}main{max-width:1460px;margin:auto;padding:36px}h1{font-size:34px;color:#ecd091;margin:0}h2{font-size:25px;color:#ecd091;margin:40px 0 14px}p{max-width:1000px}small,.note{color:#b2bcad}button,select{font:inherit;color:#eee6cd;border:1px solid #917749;background:#242f26;padding:7px 15px;cursor:pointer}button:focus-visible{outline:3px solid #ecd091}button[aria-pressed=true]{background:#65572f}.row{display:flex;gap:32px;align-items:center;flex-wrap:wrap}.sample{flex:1;min-width:370px;border-top:1px solid #48513e;padding:20px 0}.sample canvas{display:block;margin:auto;image-rendering:pixelated}img{max-width:100%;image-rendering:pixelated}figure{margin:12px 0}figcaption{color:#b2bcad;font-size:15px}.menu{width:380px;height:55px;position:relative;display:flex;align-items:center;padding-left:55px;color:#eee7cd;margin:14px 0}.menu>img{position:absolute;inset:0;width:100%;height:100%;z-index:-1}.menu .badge{width:32px;height:32px;inset:10px auto auto 10px;z-index:0}.menu{isolation:isolate}.tools{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.stage{width:100%;aspect-ratio:16/9;position:relative;overflow:hidden;background:#000;touch-action:none;user-select:none}.scene{position:absolute;width:1920px;height:1080px;transform-origin:top left}.scene>img{width:1920px;height:1080px;position:absolute;inset:0}.selection{position:absolute;border:3px dashed #d2b66e;background:#d2b66e08;display:none;pointer-events:none}.selection:before,.selection:after{content:'';position:absolute;inset:-5px;border:3px solid #ecd091;clip-path:polygon(0 0,30px 0,30px 3px,3px 3px,3px 30px,0 30px,0 0,100% 0,100% 30px,calc(100% - 3px) 30px,calc(100% - 3px) 3px,calc(100% - 30px) 3px,calc(100% - 30px) 0,100% 0,100% 100%,0 100%)}#pop{position:absolute;display:none;image-rendering:pixelated}#status{min-height:30px;color:#ecd091}.gallery{display:flex;flex-wrap:wrap;gap:25px;align-items:start}.gallery figure{max-width:45%}.gallery img{max-height:380px;object-fit:contain;object-position:left}.zoom{overflow:auto;border-top:1px solid #48513e}.zoom img{max-width:none;width:880px}table{border-collapse:collapse;width:100%;max-width:1000px}td,th{padding:9px 14px;text-align:left;border-bottom:1px solid #48513e}a{color:#ecd091}@media(max-width:650px){main{padding:20px}.sample{min-width:280px}.gallery figure{max-width:100%}}
</style><main>
<h1>분대 명령 · 둥근 바퀴</h1><p>Shift + 왼쪽 끌기로 분대를 고르고, 버튼을 놓은 자리에서 북·동·남·서를 누릅니다. 성벽을 왼쪽 누르면 보낼 병력부터 고릅니다. 새 명령 메뉴는 원형 조각으로만 구성했습니다.</p><p class="note">에셋 검토용 · 게임 연결 전 / 기존 지도 캡처와 지정된 밤 화면을 사용한 합성입니다. 이 페이지는 이미지와 코드를 내장하여 서버 없이 열립니다.</p>
<div class="row"><section class="sample"><h2>기존 가운데 버튼 명령 메뉴</h2><p>게임에 있는 목재 띠·숫자 배지·금색 붓선을 그대로 표시했습니다.</p><div id="oldMenu"></div></section><section class="sample"><h2>새 방향 바퀴 · 222px</h2><canvas id="direction" width="222" height="222" aria-label="북 동 남 서 방향 바퀴"></canvas><p>위 북 · 오른쪽 동 · 아래 남 · 왼쪽 서<br>가운데 40명은 인원 표시 자리입니다.</p></section><section class="sample"><h2>새 병력 바퀴 · 360px</h2><canvas id="amount" width="360" height="360" aria-label="보낼 병력 선택 바퀴"></canvas><p>숫자 배지와 금색 밑줄은 기존 게임 그림입니다.</p></section></div>
<div class="tools"><button id="animate" aria-pressed="true">상태 자동 미리보기 켜짐</button><button id="disabled" aria-pressed="false">사용 불가 비교</button></div><p class="note">바퀴 위로 포인터를 옮기면 강조됩니다. 사용 불가는 채도를 낮추고 빗금을 추가했습니다. 가운데와 조각 사이 틈은 선택되지 않습니다.</p>
<h2>조작 흐름 미리보기</h2><p>아래 지도에서 <b>Shift + 왼쪽 끌기 → 놓기</b>를 시험하세요. 지도 성벽 부근을 왼쪽 누르면 병력 바퀴가 뜹니다. 이 검토에서는 성벽 판정 대신 지도 클릭으로 흐름을 보여줍니다. Esc로 닫습니다.</p><div class="tools"><button id="flowA">상자 선택 결과 보기</button><button id="flowB">성벽 클릭 결과 보기</button><button id="reset">닫기</button></div><div class="stage" id="stage"><div class="scene" id="scene"><img id="map" alt="저장소에 보관된 예전 지도 화면"><div class="selection" id="box"></div><canvas id="pop" aria-label="커서 위치의 원형 선택 바퀴"></canvas></div></div><p id="status" aria-live="polite">조작을 기다립니다.</p><p class="note">지도 출처: K-020의 저장 캡처(reference_map.png). 최신 게임 지도를 새로 캡처한 화면은 아닙니다. 화면 가장자리에서는 바퀴가 잘리지 않게 안쪽으로 이동합니다.</p>
<h2>1920 × 1080 합성본</h2><div class="tools" id="shots"></div><figure><img id="mockup" alt="선택한 단계의 전체 화면 합성본"><figcaption id="shotCaption"></figcaption></figure>
<h2>조각과 격자 확인</h2><p>각 행은 기본 → 강조 → 사용 불가, 각 열은 북·동·남·서 또는 1분대·절반·전체입니다. 개별 PNG와 4배 최근접 미리보기도 에셋 폴더에 있습니다.</p><div class="gallery"><figure><img data-asset="direction_states_sheet" alt="방향 조각 12개"><figcaption>방향: 222 × 222 칸 / 4열 × 3행</figcaption></figure><figure><img data-asset="amount_states_sheet" alt="병력 조각 9개"><figcaption>병력: 360 × 360 칸 / 3열 × 3행</figcaption></figure></div><div class="zoom"><img data-asset="overview" alt="목재 원형 바퀴와 선택 표시 전체"></div>
<h2>연결 기준</h2><table><tr><th>항목</th><th>규격</th></tr><tr><td>방향</td><td>원본 74 × 74 → 3배 222 × 222 / 중심 (111, 111)</td></tr><tr><td>병력</td><td>원본 120 × 120 → 3배 360 × 360 / 중심 (180, 180)</td></tr><tr><td>선택 상자</td><td>24 × 24 모서리 + 24 × 6 가로 점선 / 세로 점선 별도</td></tr><tr><td>깃발 아래 선택 고리</td><td>72 × 30 / 중심을 깃대 접지점에 정렬</td></tr><tr><td>9분할</td><td>전체 사용 안 함. 원형 비율 고정 / 점선은 타일 반복</td></tr><tr><td>실제 인원과 명령</td><td>게임 코드에서 처리 / 40명은 표시 예시</td></tr></table><p class="note">캐릭터용 96 × 128 칸과 발 기준은 이 UI에 적용하지 않습니다. Unity 실행·Play·실제 게임 입력 검증은 수행하지 않았습니다.</p>
</main><script>
const A=__DATA__,I={},dirs=['north','east','south','west'],names=['one','half','all'],words=['북','동','남','서'],labels=['1분대 보내기','1/2 보내기','전체 보내기'];
const ready=Promise.all(Object.entries(A).map(([k,v])=>new Promise((ok,bad)=>{let im=new Image;im.onload=()=>{I[k]=im;ok()};im.onerror=()=>bad(k);im.src=v})));let auto=true,locked=false,tick=0,dh=-1,ah=-1;
function draw(c,kind,hover=-1){let g=c.getContext('2d'),isD=kind==='direction',n=isD?222:360;g.clearRect(0,0,n,n);g.imageSmoothingEnabled=false;const put=(k,x=0,y=0,w,h)=>w?g.drawImage(I[k],x,y,w,h):g.drawImage(I[k],x,y);if(isD){put('direction_base');dirs.forEach((d,i)=>put('direction_'+d+'_'+(locked?'disabled':i===hover?'hover':'normal')));put('direction_hub',66,66);let lp=[[111,46],[176,111],[111,176],[46,111]],ap=[[111,20],[202,111],[111,202],[20,111]];dirs.forEach((d,i)=>{g.globalAlpha=locked?.4:1;put('compass_'+d,lp[i][0]-18,lp[i][1]-18);g.globalAlpha=1;if(!locked){let a=I['pointer_'+d];put('pointer_'+d,ap[i][0]-a.width/2,ap[i][1]-a.height/2)}});text('40명',111,111,22)}else{let p=[[180,75],[264,235],[96,235]];names.forEach((d,i)=>{put('amount_'+d+'_'+(locked?'disabled':i===hover?'hover':'normal'));g.globalAlpha=locked?.4:1;put('icon_'+d,p[i][0]-27,p[i][1]-39);text(labels[i],p[i][0],p[i][1]+24,24);put('command_number_'+(i+1),p[i][0]-12,p[i][1]+42,24,24);if(i===hover&&!locked)put('command_underline',p[i][0]-59,p[i][1]+37,118,5);g.globalAlpha=1});put('amount_hub',141,141);text('병력',180,180,20)}function text(s,x,y,size){g.font='bold '+size+'px "Malgun Gothic",sans-serif';g.textAlign='center';g.textBaseline='middle';g.lineWidth=3;g.strokeStyle='#0a0e0d';g.strokeText(s,x,y);g.fillStyle='#ecd091';g.fillText(s,x,y)}}
function sector(c,e,kind){let r=c.getBoundingClientRect(),n=c.width,x=(e.clientX-r.left)*n/r.width-n/2,y=(e.clientY-r.top)*n/r.height-n/2,d=Math.hypot(x,y),isD=kind==='direction';if(d<(isD?48:45)||d>(isD?108:177))return -1;let a=(Math.atan2(y,x)*180/Math.PI+450)%360,step=isD?90:120,i=Math.round(a/step)%(isD?4:3),delta=Math.abs(((a-i*step+540)%360)-180);return delta<step/2-2?i:-1}
function refresh(){draw(direction,'direction',dh>=0?dh:auto?tick%4:-1);draw(amount,'amount',ah>=0?ah:auto?tick%3:-1)}
const direction=document.getElementById('direction'),amount=document.getElementById('amount'),pop=document.getElementById('pop'),stage=document.getElementById('stage'),scene=document.getElementById('scene'),box=document.getElementById('box'),status=document.getElementById('status');
ready.then(()=>{document.querySelectorAll('[data-asset]').forEach(e=>e.src=A[e.dataset.asset]);document.getElementById('map').src=A.map_source;['명령하기','전령 부르기','소리 지르기'].forEach((s,i)=>{let d=document.createElement('div');d.className='menu';d.innerHTML='<img alt="기존 목재 띠" src="'+A.command_band_normal+'"><img class="badge" alt="'+(i+1)+'" src="'+A['command_number_'+(i+1)]+'">'+s;d.firstChild.alt='기존 목재 띠';d.onmouseenter=()=>d.firstChild.src=A.command_band_hover;d.onmouseleave=()=>d.firstChild.src=A.command_band_normal;oldMenu.append(d)});refresh();showShot('mockup_a_selection_direction');document.documentElement.dataset.imagesLoaded=Object.keys(I).length}).catch(k=>{status.textContent='이미지 확인 필요: '+k;document.documentElement.dataset.imageError=k});
direction.onpointermove=e=>{dh=sector(direction,e,'direction');refresh()};direction.onpointerleave=()=>{dh=-1;refresh()};amount.onpointermove=e=>{ah=sector(amount,e,'amount');refresh()};amount.onpointerleave=()=>{ah=-1;refresh()};setInterval(()=>{tick++;if(I.direction_base)refresh()},900);
animate.onclick=()=>{auto=!auto;animate.setAttribute('aria-pressed',auto);animate.textContent='상태 자동 미리보기 '+(auto?'켜짐':'꺼짐');refresh()};disabled.onclick=()=>{locked=!locked;disabled.setAttribute('aria-pressed',locked);refresh();if(mode)draw(pop,mode)};
let mode='',anchor=[960,500],start=null,dragged=false;function fit(){scene.style.transform='scale('+stage.clientWidth/1920+')'}new ResizeObserver(fit).observe(stage);fit();function point(e){let r=stage.getBoundingClientRect();return [(e.clientX-r.left)*1920/r.width,(e.clientY-r.top)*1080/r.height]};function open(kind,p){mode=kind;anchor=p;let n=kind==='direction'?222:360;pop.width=pop.height=n;pop.style.left=Math.max(0,Math.min(1920-n,p[0]-n/2))+'px';pop.style.top=Math.max(0,Math.min(1080-n,p[1]-n/2))+'px';pop.style.display='block';draw(pop,kind);status.textContent=kind==='direction'?'보낼 방향을 고르세요.':'보낼 병력을 고르세요.'}function close(){mode='';pop.style.display='none';box.style.display='none';status.textContent='닫았습니다.'}
stage.onpointerdown=e=>{if(e.button!==0||e.target===pop)return;if(e.shiftKey){start=point(e);dragged=false;stage.setPointerCapture(e.pointerId);close();box.style.display='block'}};stage.onpointermove=e=>{if(!start)return;let p=point(e);dragged=Math.hypot(p[0]-start[0],p[1]-start[1])>6;Object.assign(box.style,{left:Math.min(p[0],start[0])+'px',top:Math.min(p[1],start[1])+'px',width:Math.abs(p[0]-start[0])+'px',height:Math.abs(p[1]-start[1])+'px'})};stage.onpointerup=e=>{if(e.button!==0||e.target===pop)return;if(start){let p=point(e);start=null;if(dragged){open('direction',p);status.textContent='상자를 놓았습니다. 4분대 · 40명 예시 → 방향을 고르세요.'}else box.style.display='none'}else if(!e.shiftKey)open('amount',point(e))};pop.onpointermove=e=>draw(pop,mode,sector(pop,e,mode));pop.onclick=e=>{e.stopPropagation();let i=sector(pop,e,mode);if(i<0||locked)return;if(mode==='amount'){let p=anchor;open('direction',p);status.textContent=labels[i]+' 선택 → 보낼 방향을 고르세요.'}else{close();status.textContent=words[i]+'쪽 보내기 선택 완료 · 검토용 표시이며 실제 명령은 전송하지 않습니다.'}};document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});flowA.onclick=()=>open('direction',[1110,470]);flowB.onclick=()=>open('amount',[960,500]);reset.onclick=close;
const shotList=[['mockup_a_selection_direction','지도 · 상자 → 방향'],['mockup_b1_amount','지도 · 병력 선택'],['mockup_b2_direction','지도 · 이어서 방향'],['mockup_a_selection_direction_night','밤 · 상자 → 방향'],['mockup_b1_amount_night','밤 · 병력 선택'],['mockup_b2_direction_night','밤 · 이어서 방향']];function showShot(k){mockup.src=A[k];shotCaption.textContent=k.includes('night')?'지정된 밤 비교 이미지의 오른쪽 위 0.35 화면을 사용한 합성 · 1920 × 1080':'K-020 저장 지도 캡처를 사용한 합성 · 1920 × 1080';document.querySelectorAll('#shots button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.key===k))}shotList.forEach(([k,s])=>{let b=document.createElement('button');b.textContent=s;b.dataset.key=k;b.onclick=()=>showShot(k);shots.append(b)});
</script></html>
